layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: var(--ryt-header-text); border-left: 5px solid var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 24px; padding-bottom: 20px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(249, 250, 251); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid color-mix(in srgb, var(--ryt-border) 50%, transparent); border-radius: 0px; transition: all; border-right: none; border-bottom: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
[data-ryt="brand"] { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 800; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); background-color: rgba(46, 51, 61, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
[data-ryt="button"] { color: var(--ryt-header-bg); background-color: var(--ryt-bg); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 6px; box-shadow: rgba(51, 51, 51, 0.05) 0px 1px 2px 0px, rgba(51, 51, 51, 0.05) 0px 2px 4px 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7px; padding-right: 15px; padding-bottom: 7px; padding-left: 15px; transition: background-color 0.294s, border-color 0.294s, box-shadow 0.294s, color 0.294s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); background-color: var(--ryt-header-text); border-radius: 6px 0px 0px 6px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 9px; padding-bottom: 0px; padding-left: 9px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 800; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 800; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
